SourceCode.Declaration:
/// <summary>
/// MPJ_5012_RebateProcess
/// Class is responsible for copying Rebate deal's Rebate table records
/// </summary>
[ExtensionOf(classStr(TAMRebateDealCopy))]
final class METTAMRebateDealCopy_Extension
{
}

Method.Source:
    /// <summary>
    /// Method to copy Rebate table Record of the rebate Deal
    /// </summary>
    /// <param name = "_rebateTable"> Copied Rebate table record </param>
    /// <param name = "_toRebateDealRecId"> Rebate Deal Record Id </param>
    /// <returns> New Rebate table record </returns>
    protected TAMRebateTable copyRebateTable(TAMRebateTable _rebateTable, RefRecId _toRebateDealRecId)
    {
        RefRecId    rebateLineAttributeRule;

        rebateLineAttributeRule = _rebateTable.PricingRuleLine;

        TAMRebateTable copiedRebateTable = next copyRebateTable(_rebateTable, _toRebateDealRecId);

        copiedRebateTable = TAMRebateCopy::METCopyRebateTableAttributeExcludeForPayment(copiedRebateTable.RebateId, rebateLineAttributeRule);

        return copiedRebateTable;
    }
